					Author:  "future-architect",
					Name:    "vuls",
					Version: fmt.Sprintf("%s-%s", result.ReportedVersion, result.ReportedRevision),
				},
			},
		},
		Component: &cdx.Component{
			BOMRef: uuid.NewString(),
			Type:   cdx.ComponentTypeOS,
			Name:   result.ServerName,
